import{_ as r,a as t,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Search Terms","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/search-terms/index.md","filePath":"api/graphql-api/admin/marketing/search-seo/search-terms/index.md","lastUpdated":1787725411000}'),s={name:"api/graphql-api/admin/marketing/search-seo/search-terms/index.md"};function d(n,e,i,c,h,l){return a(),t("div",null,e[0]||(e[0]=[o('<h1 id="search-terms" tabindex="-1">Search Terms <a class="header-anchor" href="#search-terms" aria-label="Permalink to &quot;Search Terms&quot;">​</a></h1><p>A <strong>search term</strong> is a phrase a shopper typed into storefront search, recorded automatically every time it is used. It mirrors the admin <strong>Marketing → Search &amp; SEO → Search Terms</strong> screen, where you can review what people are looking for and optionally redirect a query to a fixed URL.</p><h2 id="how-a-search-term-works" tabindex="-1">How a search term works <a class="header-anchor" href="#how-a-search-term-works" aria-label="Permalink to &quot;How a search term works&quot;">​</a></h2><p>Search terms are not created by hand — the storefront records each search and tracks how it performed.</p><ul><li><strong><code>term</code></strong> — the exact phrase the shopper searched for.</li><li><strong><code>results</code></strong> — how many products the search returned. Recorded automatically; read-only.</li><li><strong><code>uses</code></strong> — how many times the term has been searched. Recorded automatically; read-only. Sort by <code>uses</code> descending to surface the most-searched phrases.</li><li><strong><code>redirectUrl</code></strong> — an optional URL the search redirects to. Set this to send a popular query straight to a chosen page (for example, a curated landing page).</li><li><strong><code>channel</code> / <code>locale</code></strong> — the storefront context the search was recorded in. <code>channel</code> is a detail-only object (<code>{ id, _id, code, name }</code>); it is <code>null</code> on list rows.</li></ul><p><strong>What you can edit.</strong> Only <code>term</code> and <code>redirectUrl</code> are editable. The recorded metrics (<code>results</code>, <code>uses</code>) reflect real shopper behaviour and cannot be changed. There is <strong>no create</strong> operation — terms originate from the storefront.</p><p><strong>Relation to other menus.</strong> Search terms reveal what shoppers want and where search falls short. Phrases that return few or no results are good candidates for <strong>Search Synonyms</strong>, which widen storefront search recall so those queries match more products.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-terms-list.html">List</a></td><td><code>adminMarketingSearchTerms</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-terms-detail.html">Detail</a></td><td><code>adminMarketingSearchTerm</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-terms-update.html">Update</a></td><td><code>updateAdminMarketingSearchTerm</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-terms-delete.html">Delete</a></td><td><code>deleteAdminMarketingSearchTerm</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-terms-mass-delete.html">Mass Delete</a></td><td><code>createAdminMarketingSearchTermMassDelete</code> mutation</td></tr></tbody></table>',9)]))}const g=r(s,[["render",d]]);export{p as __pageData,g as default};
